const SocialLink = ({ href, icon: Icon, label }) => {
	const handleClick = () => {
		ReactGA.event({
			category: "Social Link",
			action: "click",
			label: label || href,
		});
	};

	return (
		<a
			href={href}
			target='_blank'
			rel='noopener noreferrer'
			onClick={handleClick}
			className='text-gray-600 dark:text-slate-400 hover:text-purple-600 dark:hover:text-violet-400 transition-colors'
		>
			<Icon size={23} />
		</a>
	);
};

