import { Menu, Moon, Sun, X } from "lucide-react";
import React, { useEffect, useState } from "react";

const NavButton = ({ active, onClick, children }) => (
  <button
    onClick={onClick}
    className={`relative px-3 py-2 transition-all duration-300 rounded-lg ${
      active 
        ? "text-purple-700 dark:text-purple-400 bg-purple-100 dark:bg-purple-900/30 font-medium"
        : "text-gray-600 dark:text-gray-300 hover:text-purple-600 dark:hover:text-purple-400 hover:bg-purple-50 dark:hover:bg-purple-900/20"
    }`}
  >
    {children}
  </button>
);

const ThemeToggle = ({ isDark, onToggle }) => (
  <button
    onClick={onToggle}
    className="p-2 rounded-lg bg-purple-50 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 hover:bg-purple-100 dark:hover:bg-purple-900/50 transition-all"
    aria-label="Toggle theme"
  >
    {isDark ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
  </button>
);

const MobileMenu = ({ isOpen, navItems, activeSection, onItemClick, isDark, onThemeToggle, onClose }) => (
  <div className={`xl:hidden fixed inset-0 z-50 ${isOpen ? 'pointer-events-auto' : 'pointer-events-none'}`}>
    <div 
      className={`absolute inset-0 bg-black/50 transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}
      onClick={onClose}
    />
    <div className={`absolute inset-y-0 right-0 w-full sm:max-w-sm bg-white dark:bg-gray-900 transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
      <div className="flex flex-col h-full">
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-800">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Menu</h2>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-gray-600 dark:text-gray-300 hover:bg-purple-50 dark:hover:bg-purple-900/20"
          >
            <X className="w-6 h-6" />
          </button>
        </div>
        <div className="flex-1 overflow-y-auto p-4">
          <div className="space-y-4">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => onItemClick(item.id)}
                className={`w-full text-left px-4 py-3 rounded-lg transition-all ${
                  activeSection === item.id
                    ? "bg-purple-100 dark:bg-purple-900/30 text-purple-700 dark:text-purple-400"
                    : "text-gray-600 dark:text-gray-300"
                }`}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
        <div className="p-4 border-t border-gray-200 dark:border-gray-800">
          <ThemeToggle isDark={isDark} onToggle={onThemeToggle} />
        </div>
      </div>
    </div>
  </div>
);

const navItems = [
  { id: "about", label: "About" },
  { id: "research", label: "Research" },
  { id: "publications", label: "Publications" },
  { id: "experience", label: "Experience" },
  { id: "teaching", label: "Teaching" },
  { id: "education", label: "Education" },
  { id: "certifications", label: "Certifications" },
  { id: "creative-life", label: "Creative Life" },
  { id: "literary-odyssey", label: "My Bookshelf" },
];
const Navigation = () => {
  const [activeSection, setActiveSection] = useState("about");
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(null);


  useEffect(() => {
    if (typeof window === 'undefined') return;

    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark') {
      setIsDark(true);
    } else if (storedTheme === 'light') {
      setIsDark(false);
    } else {
      setIsDark(systemPrefersDark);
    }

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleChange = (e) => {
      if (!localStorage.getItem('theme')) {
        setIsDark(e.matches);
      }
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  useEffect(() => {
    if (isDark === null) return;
    
    if (isDark) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }
  }, [isDark]);

  const handleThemeToggle = () => {
    const newTheme = !isDark;
    setIsDark(newTheme);
    localStorage.setItem('theme', newTheme ? 'dark' : 'light');
  };

  useEffect(() => {
    const options = {
      root: null,
      rootMargin: "-50% 0px",
      threshold: 0
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    }, options);

    navItems.forEach(({ id }) => {
      const element = document.getElementById(id);
      if (element) observer.observe(element);
    });

    return () => {
      navItems.forEach(({ id }) => {
        const element = document.getElementById(id);
        if (element) observer.unobserve(element);
      });
    };
  }, []);

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      const navHeight = 80;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - navHeight;

      window.scrollTo({
        top: offsetPosition,
        behavior: "smooth"
      });
      setIsMobileMenuOpen(false);
    }
  };

  if (isDark === null) {
    return null;
  }

  return (
    <header className="fixed top-0 left-0 right-0 z-50 w-auto bg-white dark:bg-gray-900 border-b border-purple-100 dark:border-purple-900/50 shadow-sm">
      <div className="max-w-7xl mx-auto px-4">
        <nav className="py-4">
          <div className="flex justify-between items-center">
            <h1 className="text-2xl font-bold bg-gradient-to-r from-purple-600 to-indigo-600 dark:from-purple-400 dark:to-indigo-400 bg-clip-text text-transparent">
              Srikrishna S Kashyap
            </h1>
            
            {/* Desktop Navigation */}
            <div className="hidden xl:flex items-center space-x-4">
              <div className="flex space-x-1">
                {navItems.map((item) => (
                  <NavButton
                    key={item.id}
                    active={activeSection === item.id}
                    onClick={() => scrollToSection(item.id)}
                  >
                    {item.label}
                  </NavButton>
                ))}
              </div>
              <ThemeToggle isDark={isDark} onToggle={handleThemeToggle} />
            </div>

            {/* Mobile/Tablet Menu Button */}
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="xl:hidden p-2 rounded-lg text-gray-600 dark:text-gray-300 hover:bg-purple-50 dark:hover:bg-purple-900/20"
              aria-label="Toggle mobile menu"
            >
              {isMobileMenuOpen ? (
                <X className="w-6 h-6" />
              ) : (
                <Menu className="w-6 h-6" />
              )}
            </button>
          </div>
        </nav>
      </div>

      {/* Mobile/Tablet Menu */}
      <MobileMenu
        isOpen={isMobileMenuOpen}
        navItems={navItems}
        activeSection={activeSection}
        onItemClick={scrollToSection}
        isDark={isDark}
        onThemeToggle={handleThemeToggle}
        onClose={() => setIsMobileMenuOpen(false)}
      />
    </header>
  );
};

export default Navigation;