// Base themed components
const ThemedSection = ({ title, icon: Icon, children }) => (
	<section id='experience' className='mb-16'>
		<h2 className='text-3xl font-bold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2'>
			<Icon className='w-8 h-8 text-purple-600 dark:text-violet-400' />
			{title}
		</h2>
		{children}
	</section>
);

const MetricsDisplay = ({ metrics }) => (
	<div className='grid grid-cols-2 md:grid-cols-3 gap-4 mb-4'>
		{metrics.map((item, index) => (
			<div
				key={index}
				className='bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/50 dark:to-slate-900/50 rounded-lg p-3 text-center backdrop-blur-sm'
			>
				<div className='text-lg font-bold text-purple-600 dark:text-violet-400'>
					{item.value}
				</div>
				<div className='text-xs text-gray-600 dark:text-slate-300'>
					{item.metric}
				</div>
			</div>
		))}
	</div>
);

const TechTag = ({ children }) => (
	<span className='text-xs bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-500 dark:to-fuchsia-500 text-white px-2 py-1 rounded-full hover:from-purple-600 hover:to-indigo-600 dark:hover:from-violet-600 dark:hover:to-fuchsia-600 transition-all duration-300'>
		{children}
	</span>
);

const ExternalLink = ({ url, text }) => {
	const handleClick = () => {
		ReactGA.event({
			category: "Experience",
			action: "external_link_click",
			label: `${text} - ${url}`,
		});
	};
	return (
		<a
			href={url}
			target='_blank'
			rel='noopener noreferrer'
			onClick={handleClick}
			className='inline-flex items-center gap-1 px-3 py-1 text-sm bg-purple-50 dark:bg-violet-500/20 text-purple-600 dark:text-violet-400 hover:bg-purple-100 dark:hover:bg-violet-500/30 rounded-full transition-colors'
		>
			<Globe className='w-4 h-4' />
			{text}
		</a>
	);
};

const BulletPoint = ({ children }) => (
	<li className='text-sm text-gray-600 dark:text-slate-300 flex items-start gap-2'>
		<span className='w-1.5 h-1.5 bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-400 dark:to-fuchsia-400 rounded-full mt-1.5'></span>
		<span>{children}</span>
	</li>
);

const ExperienceCard = ({
	icon,
	title,
	company,
	location,
	period,
	description,
	achievements,
	impact,
	technologies,
	externalLinks,
	images,
	imageDescriptions,
}) => {
	const [open, setOpen] = useState(false);
	const [index, setIndex] = useState(0);

	const slides = images
		? images.map((image, idx) => ({
				src: image,
				alt: imageDescriptions?.[idx] || "",
				title: title,
				description: imageDescriptions?.[idx] || "",
		  }))
		: [];

	const handleImageClick = (imageIndex) => {
		// Track image click
		ReactGA.event({
			category: "Experience",
			action: "image_click",
			label: `${company} - ${title} - ${
				imageDescriptions?.[imageIndex] || images[imageIndex]
			}`,
		});
		setIndex(imageIndex);
		setOpen(true);
	};

	const handleLightboxClose = () => {
		ReactGA.event({
			category: "Experience",
			action: "lightbox_close",
			label: `${company} - ${title}`,
		});
		setOpen(false);
	};

	const displayImages = images ? images.slice(0, 2) : [];
	const remainingImagesCount = images ? images.length - 2 : 0;

	return (
		<div className='bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90 rounded-lg shadow-md dark:shadow-lg dark:shadow-slate-900/50 p-6 hover:shadow-lg transition-all duration-300'>
			<div className='flex items-start justify-between mb-4'>
				<div>
					<div className='flex items-center gap-2 mb-2'>
						<div className='p-2 bg-white dark:bg-slate-800/50 rounded-lg shadow-sm border border-transparent dark:border-violet-500/20'>
							{React.cloneElement(icon, {
								className: "w-6 h-6 text-purple-600 dark:text-violet-400",
							})}
						</div>
						<h3 className='text-xl font-semibold text-gray-800 dark:text-slate-50'>
							{title}
						</h3>
					</div>
					<p className='text-gray-600 dark:text-slate-300'>
						{company} • {location}
					</p>
					<div className='text-sm font-medium text-purple-600 dark:text-violet-400 bg-purple-50 dark:bg-violet-500/20 px-3 py-1 rounded-full inline-block mt-2'>
						{period}
					</div>
				</div>
			</div>

			<p className='text-gray-600 dark:text-slate-300 mb-4'>{description}</p>

			{/* Images Section */}
			{images && images.length > 0 && (
				<div className='mt-6 mb-6'>
					<div className='grid grid-cols-2 gap-4'>
						{displayImages.map((image, idx) => (
							<div
								key={idx}
								className='relative group cursor-pointer overflow-hidden rounded-lg'
								onClick={() => handleImageClick(idx)}
							>
								<img
									src={image}
									alt={imageDescriptions?.[idx] || ""}
									className='w-full h-48 object-cover transition-transform duration-300 group-hover:scale-110'
								/>
								{idx === 1 && remainingImagesCount > 0 && (
									<div className='absolute inset-0 bg-black bg-opacity-60 flex flex-col items-center justify-center text-white'>
										<ImageIcon className='w-8 h-8 mb-2' />
										<span className='text-lg font-semibold'>
											+{remainingImagesCount} more
										</span>
									</div>
								)}
								{idx !== 1 && (
									<div className='absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-40 transition-all duration-300 flex items-center justify-center'>
										<div className='text-white text-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 p-4'>
											<p className='text-sm'>
												{imageDescriptions?.[idx] || ""}
											</p>
										</div>
									</div>
								)}
							</div>
						))}
					</div>

					<Lightbox
						open={open}
						close={handleLightboxClose}
						index={index}
						slides={slides}
						plugins={[Thumbnails, Zoom, Slideshow]}
						thumbnails={{
							position: "bottom",
							width: 120,
							height: 80,
						}}
						zoom={{
							maxZoomPixelRatio: 3,
							scrollToZoom: true,
						}}
						slideshow={{
							autoplay: true,
							delay: 3000,
						}}
						on={{
							view: ({ index }) => {
								ReactGA.event({
									category: "Experience",
									action: "image_view",
									label: `${company} - ${title} - ${
										imageDescriptions?.[index] || slides[index].src
									}`,
								});
							},
						}}
					/>
				</div>
			)}

			{/* External Links */}
			{externalLinks && externalLinks.length > 0 && (
				<div className='mb-4 flex flex-wrap gap-3'>
					{externalLinks.map((link, index) => (
						<ExternalLink key={index} {...link} />
					))}
				</div>
			)}

			{/* Achievements */}
			<div className='mb-4'>
				<h4 className='text-sm font-semibold text-gray-700 dark:text-slate-200 mb-2'>
					Key Achievements
				</h4>
				<ul className='space-y-2'>
					{achievements.map((achievement, index) => (
						<BulletPoint key={index}>{achievement}</BulletPoint>
					))}
				</ul>
			</div>

			{/* Impact Metrics */}
			{impact && <MetricsDisplay metrics={impact} />}

			{/* Technologies */}
			{technologies && (
				<div className='flex flex-wrap gap-2'>
					{technologies.map((tech, index) => (
						<TechTag key={index}>{tech}</TechTag>
					))}
				</div>
			)}
		</div>
	);
};

