import React, { useEffect } from "react";
import ReactGA from "react-ga4";
import Navigation from "./components/Header/Navigation";
import About from "./components/Sections/About";
import Research from "./components/Sections/Research";
import Publications from "./components/Sections/Publications";
import Experience from "./components/Sections/Experience";
import Teaching from "./components/Sections/Teaching";
import Footer from "./components/Footer/Footer";
import Education from "./components/Sections/Education";
import Certifications from "./components/Sections/Certifications";
import CreativeLife from "./components/Sections/CreativeLife";
import LiteraryOdyssey from "./components/Sections/LiteraryOdyssey";
import "./App.css";

const App = () => {
	useEffect(() => {
		// Initialize GA4
		ReactGA.initialize("G-NZZYEZDNPF");

		// Track initial page view
		ReactGA.send({
			hitType: "pageview",
			page: window.location.pathname,
			title: "Home Page",
		});

		// Track scroll depth
		const handleScroll = () => {
			const scrolled = window.scrollY;
			const height = document.documentElement.scrollHeight - window.innerHeight;
			const scrollPercentage = (scrolled / height) * 100;

			// Track at 25%, 50%, 75%, and 100% scroll depth
			if (scrollPercentage >= 25 && !localStorage.getItem("scroll25")) {
				ReactGA.event({
					category: "Scroll Depth",
					action: "scroll",
					label: "25%",
				});
				localStorage.setItem("scroll25", "true");
			}
			if (scrollPercentage >= 50 && !localStorage.getItem("scroll50")) {
				ReactGA.event({
					category: "Scroll Depth",
					action: "scroll",
					label: "50%",
				});
				localStorage.setItem("scroll50", "true");
			}
			if (scrollPercentage >= 75 && !localStorage.getItem("scroll75")) {
				ReactGA.event({
					category: "Scroll Depth",
					action: "scroll",
					label: "75%",
				});
				localStorage.setItem("scroll75", "true");
			}
			if (scrollPercentage >= 90 && !localStorage.getItem("scroll90")) {
				ReactGA.event({
					category: "Scroll Depth",
					action: "scroll",
					label: "90%",
				});
				localStorage.setItem("scroll90", "true");
			}
		};

		// Add scroll listener
		window.addEventListener("scroll", handleScroll);

		// Cleanup
		return () => {
			window.removeEventListener("scroll", handleScroll);
			localStorage.removeItem("scroll25");
			localStorage.removeItem("scroll50");
			localStorage.removeItem("scroll75");
			localStorage.removeItem("scroll90");
		};
	}, []);

	return (
		<div className='xl:w-full w-fit min-h-screen bg-gray-50 dark:bg-gray-900 transition-colors duration-300'>
			<header className='bg-white dark:bg-gray-900 shadow-md'>
				<Navigation />
			</header>

			<main className='w-full container mx-auto px-4 py-8'>
				<About />
				<Research />
				<Publications />
				<Experience />
				<Teaching />
				<Education />
				<Certifications />
				<CreativeLife />
				<LiteraryOdyssey />
			</main>

			<Footer />
		</div>
	);
};

export default App;
